use super::*;
use crate::pet_runtime::messages::ReceivedReference;
fn reference(r:&crate::pet_runtime::messages::Receipt)->ReceivedReference{ReceivedReference{decision_id:r.envelope().origin.decision_id.clone(),message_id:r.envelope().message_id.clone(),scope_hash:model::fingerprint(&r.scope).unwrap()}}
#[test]fn received_message_uses_the_receivers_own_signed_admission_and_is_passive(){
 let s=Setup::new();let(a,oa)=s.goal("ollama","ai_lmstudio",2,1);let(b,ob)=s.goal("lmstudio","ai_ollama",2,1);let approved=s.approved(&a,&oa,0,Arc::new(||true));let receipt=oa.send_message(&a,&approved,crate::assistant_memory::now(),||s.observe()).unwrap();let r=reference(&receipt);let row=&b.admissions[0];let before=crate::pet_runtime::reconciliation_tests::inventory(&s.f.path);
 let found=s.a.received_message(&row.spec,row.proof.as_ref().unwrap(),ob.lease(),&r,crate::assistant_memory::now()).unwrap();assert_eq!(found.reference(),&r);assert_eq!(found.envelope(),receipt.envelope());assert!(!found.envelope().provider_use_authorized);assert_eq!(crate::pet_runtime::reconciliation_tests::inventory(&s.f.path),before);assert!(s.budget(&b).is_null());
 let sender=&a.admissions[0];assert!(s.a.received_message(&sender.spec,sender.proof.as_ref().unwrap(),oa.lease(),&r,crate::assistant_memory::now()).is_err());let mut forged=row.spec.clone();forged.owner.pet_id="agent_codex".into();assert!(s.a.received_message(&forged,row.proof.as_ref().unwrap(),ob.lease(),&r,crate::assistant_memory::now()).is_err());
 for field in ["decision","message","hash"]{let mut bad=r.clone();match field{"decision"=>bad.decision_id=nonce().unwrap(),"message"=>bad.message_id=nonce().unwrap(),_=>bad.scope_hash="a".repeat(64)}assert!(s.a.received_message(&row.spec,row.proof.as_ref().unwrap(),ob.lease(),&bad,crate::assistant_memory::now()).is_err());}
 let encoded=serde_json::to_value(&r).unwrap();let mut forged=encoded.clone();forged["petId"]=json!("ai_lmstudio");assert!(serde_json::from_value::<ReceivedReference>(forged).is_err());assert_eq!(serde_json::to_value(serde_json::from_value::<ReceivedReference>(encoded.clone()).unwrap()).unwrap(),encoded);assert_eq!(crate::pet_runtime::reconciliation_tests::inventory(&s.f.path),before);
}
#[test]fn received_message_expiry_and_revoked_receiver_do_not_create_or_renew_authority(){
 let s=Setup::new();let(a,oa)=s.goal("ollama","ai_lmstudio",2,1);let(b,ob)=s.goal("lmstudio","ai_ollama",2,1);let approved=s.approved(&a,&oa,0,Arc::new(||true));let receipt=oa.send_message(&a,&approved,crate::assistant_memory::now(),||s.observe()).unwrap();let r=reference(&receipt);let row=&b.admissions[0];let before=crate::pet_runtime::reconciliation_tests::inventory(&s.f.path);
 assert!(receipt.envelope().deadline_at<ob.lease().deadline_at);assert_eq!(s.a.received_message(&row.spec,row.proof.as_ref().unwrap(),ob.lease(),&r,receipt.envelope().deadline_at).err(),Some(Failure::Expired));assert_eq!(crate::pet_runtime::reconciliation_tests::inventory(&s.f.path),before);
 s.a.request_stop(&row.spec,row.proof.as_ref().unwrap(),crate::pet_runtime::leases::StopReason::Cancel,crate::assistant_memory::now()).unwrap();let stopped=crate::pet_runtime::reconciliation_tests::inventory(&s.f.path);assert_eq!(s.a.received_message(&row.spec,row.proof.as_ref().unwrap(),ob.lease(),&r,crate::assistant_memory::now()).err(),Some(Failure::Revoked));assert_eq!(crate::pet_runtime::reconciliation_tests::inventory(&s.f.path),stopped);assert_eq!(s.a.message_inbox("ai_lmstudio",None,32,crate::assistant_memory::now()).unwrap().items[0].receipt,receipt);
}
#[test]fn received_message_never_adopts_staging_or_trusts_a_modified_receipt(){
 let mut s=Setup::new();let(a,oa)=s.goal("ollama","ai_lmstudio",2,1);let(b,ob)=s.goal("lmstudio","ai_ollama",2,1);let approved=s.approved(&a,&oa,0,Arc::new(||true));let source=&a.admissions[0];let caller=&b.admissions[0];let r=ReceivedReference{decision_id:source.spec.decision_id.clone(),message_id:approved.scope().envelope.message_id.clone(),scope_hash:model::fingerprint(approved.scope()).unwrap()};s.a.fault=Fault::BeforeGrantPublish;
 assert_eq!(s.a.deliver_message(&a,&source.spec,source.proof.as_ref().unwrap(),oa.lease(),&approved,crate::assistant_memory::now(),||true).err(),Some(Failure::Unavailable));s.a.fault=Fault::None;let before=crate::pet_runtime::reconciliation_tests::inventory(&s.f.path);assert!(s.a.received_message(&caller.spec,caller.proof.as_ref().unwrap(),ob.lease(),&r,crate::assistant_memory::now()).is_err());assert_eq!(crate::pet_runtime::reconciliation_tests::inventory(&s.f.path),before);
 let receipt=oa.send_message(&a,&approved,crate::assistant_memory::now(),||s.observe()).unwrap();let r=reference(&receipt);let path=s.f.path.join("authority").join(format!("{}.json",source.spec.decision_id));let mut data:Value=serde_json::from_slice(&fs::read(&path).unwrap()).unwrap();data["body"]["messages"]["entries"][0]["scope"]["envelope"]["recipient"]["petId"]=json!("agent_codex");fs::write(&path,serde_json::to_vec(&data).unwrap()).unwrap();let before=crate::pet_runtime::reconciliation_tests::inventory(&s.f.path);assert!(s.a.received_message(&caller.spec,caller.proof.as_ref().unwrap(),ob.lease(),&r,crate::assistant_memory::now()).is_err());assert_eq!(crate::pet_runtime::reconciliation_tests::inventory(&s.f.path),before);
}
